function validate([word, m]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 100000) return 'word needs 1 to 100000 characters.';
  if (!/^[0-9]+$/.test(word)) return 'word may contain only the digits 0 to 9.';
  if (!Number.isInteger(m) || m < 1 || m > 1000000000) return 'm is an integer between 1 and 10^9.';
  return null;
}

