function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(8000, 10000) : pick(1, 10);
  const zeroHeavy = rand() < 0.25;
  let word = '';
  for (let i = 0; i < n; i++) {
    word += zeroHeavy && rand() < 0.6 ? '0' : String(pick(0, 9));
  }
  const roll = rand();
  let m;
  if (roll < 0.5) m = pick(1, 12);
  else if (roll < 0.75) m = pick(13, 1000);
  else m = pick(1, 1000000000);
  return [word, m];
}
